221	class ShellTheme
222	{
223	public:
224	    // Loads both semantic palettes, the metrics and the text roles from the
225	    // packaged token file. Throws std::runtime_error when the file is missing
226	    // or malformed so the caller can fall back to the standard Orca
227	    // presentation. Needs no wx initialisation.
228	    static ShellTheme load_from_resources();
229	
230	    const ShellPalette& palette(bool dark) const { return dark ? m_dark : m_light; }
231	    const ShellMetrics& metrics() const { return m_metrics; }
232	    const TypeStyle&    type_style(TextRole role) const { return m_type_styles[size_t(role)]; }
233	
234	    // The wxFont for a role, built once on first use through OrcaSlicer's
235	    // Label::sysFont so it carries the same face as the rest of the
236	    // application, then sized so the role's DIP size is its em on every
237	    // platform (sysFont's own point scaling rounds the token off on Windows
238	    // and Linux). Requires wx to be initialised.
239	    const wxFont& font(TextRole role) const;
240	
241	private:
242	    ShellPalette m_light;
243	    ShellPalette m_dark;
244	    ShellMetrics m_metrics;
245	    std::array<TypeStyle, kTextRoleCount> m_type_styles{};
246	    mutable std::array<wxFont, kTextRoleCount> m_fonts{};
247	};
