 71	    '--font-code',
 72	    ...Object.entries(component.button)
 73	      .filter(([, recipe]) => recipe.paddingX !== undefined && recipe.paddingY !== undefined)
 74	      .map(([name]) => `--button-${kebab(name)}-padding`),
 75	    ...Object.entries(component.button)
 76	      .filter(([, recipe]) => recipe.iconGap !== undefined)
 77	      .map(([name]) => `--button-${kebab(name)}-icon-gap`),
 78	    '--button-icon-width', '--button-icon-height', '--button-icon-icon-size',
