 83	// Colors depend on the appearance; everything below does not, so it is
 84	// written once at startup:
 85	//   --radius-<name>       e.g. --radius-container: 8px
 86	//   --font-<role>         full `font` shorthand in the UI face, kebab-case
 87	//   --font-code           the one monospace role, for code, keys, paths, IDs
 88	//   --button-<recipe>-padding  "<y>px <x>px" from component.button; control
 89	//                         padding follows the recipes, not the spacing scale
 90	//   --button-<recipe>-icon-gap  the space between a button's icon and its
 91	//                         label, also a recipe-internal size, not a layout gap
 92	export function applySharedStaticTokens(): void {
 93	  const { dimension, typography, component } = tokens as unknown as StaticTokens;
 94	  const root = document.documentElement;
 95	  for (const [name, value] of Object.entries(dimension.radius)) {
 96	    root.style.setProperty(`--radius-${kebab(name)}`, `${value}px`);
 97	  }
 98	  const uiFamily = `'${typography.ui.family}', ${typography.ui.cssFallback}`;
 99	  for (const [name, role] of Object.entries(typography.roles)) {
100	    root.style.setProperty(`--font-${kebab(name)}`, fontShorthand(role, uiFamily));
101	  }
102	  root.style.setProperty('--font-code', fontShorthand(typography.code, typography.code.cssFamily));
103	  for (const [name, recipe] of Object.entries(component.button)) {
104	    if (recipe.iconGap === undefined) continue;
105	    root.style.setProperty(`--button-${kebab(name)}-icon-gap`, `${recipe.iconGap}px`);
106	  }
107	  for (const [name, recipe] of Object.entries(component.button)) {
108	    if (recipe.paddingX === undefined || recipe.paddingY === undefined) continue;
109	    root.style.setProperty(`--button-${kebab(name)}-padding`, `${recipe.paddingY}px ${recipe.paddingX}px`);
110	  }
111	  const icon = component.button.icon;
112	  root.style.setProperty('--button-icon-width', `${icon.width}px`);
113	  root.style.setProperty('--button-icon-height', `${icon.height}px`);
114	  root.style.setProperty('--button-icon-icon-size', `${icon.iconSize}px`);
115	  applyPixelTokens('progress', component.progress);
116	}
