131	// Every --elevation-<tier> variable applyAppearance writes. They are appearance
132	// variables rather than static ones: the geometry is shared across modes but
133	// the opacity is not, so the value is rewritten whenever the mode changes.
134	export function elevationVariableNames(): string[] {
135	  return Object.keys(elevationTiers()).map((tier) => `--elevation-${kebab(tier)}`);
136	}
