138	// "#000000" + 0.24 -> "rgba(0, 0, 0, 0.24)". The token keeps the colour as hex
139	// so it reads like every other colour in the file; CSS needs it with an alpha.
140	function rgba(hex: string, opacity: number): string {
141	  const value = hex.replace('#', '');
142	  const channel = (at: number) => parseInt(value.slice(at, at + 2), 16);
143	  return `rgba(${channel(0)}, ${channel(2)}, ${channel(4)}, ${opacity})`;
144	}
