146	// The one place a semantic color's CSS variable name is built, so
147	// semanticVariableNames() and applyAppearance() cannot drift apart the way
148	// applyAppearance's own kebab-casing once drifted from the rest of this file.
149	function semanticVariableName(group: string, name: string): string {
150	  return `--${group}-${kebab(name)}`;
151	}
152	
153	// Every --<group>-<name> variable applyAppearance writes, so a page's styles
154	// test can check that its stylesheet only asks for variables that exist. Both
155	// modes name the same variables, so light is enough to enumerate them.
156	export function semanticVariableNames(): string[] {
157	  const semantic = (tokens as { semantic: Record<string, SemanticMode> }).semantic;
158	  const names: string[] = [];
159	  for (const [group, values] of Object.entries(semantic.light)) {
160	    for (const [name, value] of Object.entries(values)) {
161	      if (typeof value === 'string') names.push(semanticVariableName(group, name));
162	    }
163	  }
164	  return names;
165	}
166	
167	export function applyAppearance(appearance: Appearance): void {
168	  const semantic = (tokens as { semantic: Record<string, SemanticMode> }).semantic;
169	  const mode = semantic[appearance] ?? semantic.light;
170	  const root = document.documentElement;
171	  for (const [group, values] of Object.entries(mode)) {
172	    for (const [name, value] of Object.entries(values)) {
173	      if (typeof value === 'string') root.style.setProperty(semanticVariableName(group, name), value);
174	    }
175	  }
176	  for (const [tier, shadow] of Object.entries(elevationTiers())) {
177	    const opacity = shadow.opacity[appearance] ?? shadow.opacity.light;
178	    root.style.setProperty(
179	      `--elevation-${kebab(tier)}`,
180	      `${shadow.offsetX}px ${shadow.offsetY}px ${shadow.blur}px ${shadow.spread}px ${rgba(shadow.color, opacity)}`,
181	    );
182	  }
183	  root.dataset.appearance = appearance;
184	}

